package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Original Hail workflows with captured complete inputs, owned execution and atomic result admission. */
public final class HailWorkflowCli {
    private HailWorkflowCli() { }
    static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, original logs, complete typed snapshots, native MatrixTable/Table/LD files and process receipts. FAIL2: the whole requested batch failed, including earlier successful cases; preserve every input/provisional output and correct the named input/runtime/operation/capacity/timeout error before retrying NEW output paths. SKIP3: dependent analysis was skipped; provide the named exact permitted Linux Hail/Python/Java11/Spark runtime and explicit installed job executables. Install only where permitted, using separate preparation paths; where forbidden keep analysis skipped. Analysis installs nothing. This profile executes LOCAL Batch only; required SERVICE/cloud analysis is skipped. No paper masks, reference-allele repair, missing-value replacement, release/build substitution or cloud scale are inferred.";
    record Captured(Path source,Path copy,NextflowFiles.Pin pin) { }
    record Executable(Path requested,Path real,NextflowFiles.Pin pin) { }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==1&&args[0].equals("--help")){output.println("java -cp DEVELOPMENT.jar org.jlinalg.cli.HailWorkflowCli --request request.json\nOriginal Hail0.2.139/0.2.130; execution requires Linux x86_64 and a separately validated exact runtime manifest.\nExplicit VCF/MatrixTable pipelines, QC/filters/annotations, LD/pruning/PCA, GRCh37-to-GRCh38 locus liftover and LOCAL Batch resource DAGs.\n"+ACTION);return 0;}
        Path out=null;int exit=2;var warnings=new ArrayList<String>();warnings.add(ACTION);var state=new LinkedHashMap<String,Object>();state.put("status","RUNNING_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("required_action",ACTION);state.put("started_at",Instant.now().toString());
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request FILE or --help");Path request=Path.of(args[1]).toAbsolutePath().normalize();byte[] raw=NextflowFiles.bytes(request,16777216);var requestPin=new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw));require(requestPin.equals(NextflowFiles.pin(request,16777216,()->{})),"Request changed during complete capture");var r=HailWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),16777216,2000000)),request.getParent());Path wanted=r.out();require(!Files.exists(wanted,LinkOption.NOFOLLOW_LINKS)&&canonicalMissing(wanted).equals(wanted),"Require NEW output under canonical unlinked parents");require(!request.startsWith(wanted)&&!r.runtime().startsWith(wanted),"Output overlaps original request/runtime manifest");
            for(var input:r.captures())require(!wanted.startsWith(input.source())&&!input.source().startsWith(wanted),"Output overlaps an original input tree");
            if(System.getProperty("os.name").equals("Linux"))for(var c:r.cases())if(text(c.get("kind")).equals("batch-local")&&text(c.get("backend")).equals("LOCAL"))require(wanted.toString().matches("/[A-Za-z0-9_./-]+"),"Original LocalBackend emits an unquoted scratch-directory cd. Choose an explicit output path containing only ASCII letters/digits, slash, underscore, dot and hyphen; do not infer a replacement path");
            if(Files.isRegularFile(r.runtime(),LinkOption.NOFOLLOW_LINKS)){
                var quick=HailWorkflowRuntime.read(r.runtime(),67108864);for(String key:List.of("runtime_environment","java_home"))if(quick.get(key) instanceof String s){Path root=canonicalMissing(Path.of(s).toAbsolutePath().normalize());require(!wanted.startsWith(root)&&!root.startsWith(wanted),"Output overlaps a read-only original runtime tree");}
            }
            Files.createDirectories(wanted.getParent());Files.createDirectory(wanted);out=wanted;Files.write(out.resolve("request.original.json"),raw,StandardOpenOption.CREATE_NEW);status(out,state);error.println("Hail: checking exact original dependencies; the complete batch remains unadmitted.");var runtime=HailWorkflowRuntime.prepare(r);require(!out.startsWith(runtime.prefix())&&!out.startsWith(runtime.javaHome())&&!runtime.prefix().startsWith(out)&&!runtime.javaHome().startsWith(out),"Output overlaps original runtime");
            var executables=new ArrayList<Executable>();
            for(Path path:r.executables()){
                try{Path real=path.toRealPath();require(Files.isExecutable(path)&&Files.isRegularFile(real,LinkOption.NOFOLLOW_LINKS),"Required declared job executable unavailable: "+path);executables.add(new Executable(path,real,NextflowFiles.pin(real,Integer.MAX_VALUE,()->{})));}
                catch(IOException failure){throw new HailWorkflowRuntime.Unavailable("Required job executable unavailable; skip dependent Batch analysis. Supply the named installed permitted tool: "+path,failure);}
            }
            Files.createDirectory(out.resolve("inputs"));var captured=new ArrayList<Captured>();var inputRecords=new ArrayList<Map<String,Object>>();long[] inputBytes={0};int[] inputFiles={0};
            for(var input:r.captures()){
                Path source=input.source(),container=out.resolve("inputs").resolve(input.id());Files.createDirectory(container);Path copy=container.resolve(source.getFileName());require(source.toRealPath().equals(source)&&!Files.isSymbolicLink(source),"Input root must be canonical and unlinked: "+source);var files=new LinkedHashMap<String,Object>();var directories=new ArrayList<String>();
                if(input.directory()){
                    require(Files.isDirectory(source,LinkOption.NOFOLLOW_LINKS),"Declared MatrixTable input directory missing");Files.createDirectory(copy);directories.add("");
                    Files.walkFileTree(source,new SimpleFileVisitor<>(){
                        @Override public FileVisitResult preVisitDirectory(Path path,BasicFileAttributes attrs)throws IOException{require(!Files.isSymbolicLink(path),"Linked source directory");if(!path.equals(source)){require(++inputFiles[0]<=r.maximumFiles(),"Complete input member capacity exceeded");Path relative=source.relativize(path);Files.createDirectory(copy.resolve(relative));directories.add(relative.toString().replace('\\','/'));}return FileVisitResult.CONTINUE;}
                        @Override public FileVisitResult visitFile(Path path,BasicFileAttributes attrs)throws IOException{require(attrs.isRegularFile()&&!attrs.isSymbolicLink(),"Nonregular/linked original input member");Path relative=source.relativize(path);var pin=capture(path,copy.resolve(relative),r,inputBytes,inputFiles);captured.add(new Captured(path,copy.resolve(relative),pin));files.put(relative.toString().replace('\\','/'),pinObject(pin));return FileVisitResult.CONTINUE;}
                    });
                }else{var pin=capture(source,copy,r,inputBytes,inputFiles);captured.add(new Captured(source,copy,pin));files.put("",pinObject(pin));}
                inputRecords.add(Map.of("id",input.id(),"original_path",source.toString(),"captured_path",copy.toString(),"directory",input.directory(),"directories",directories,"files",files));
            }
            NextflowFiles.writeJson(out.resolve("input-capture.json"),inputRecords);NextflowFiles.writeJson(out.resolve("effective-request.json"),r.worker(runtime.expectedVersion()));Path worker=Files.createDirectory(out.resolve("worker"));error.println("Hail: executing the explicit original workflow batch.");var report=HailWorkflowRuntime.run(worker,r,runtime);validateCases(worker,r,report);error.println("Hail: checking every input, runtime member and final native result before admission.");runtime.verify();
            for(var input:captured)require(input.pin().equals(NextflowFiles.pin(input.source(),r.inputBytes(),()->{}))&&input.pin().equals(NextflowFiles.pin(input.copy(),r.inputBytes(),()->{})),"Original or captured input changed during the batch: "+input.source());
            for(var executable:executables)require(executable.requested().toRealPath().equals(executable.real())&&executable.pin().equals(NextflowFiles.pin(executable.real(),Integer.MAX_VALUE,()->{})),"Declared job executable changed during Batch execution");require(requestPin.equals(NextflowFiles.pin(request,16777216,()->{})),"Original request changed during execution");
            Path stderr=worker.resolve("original.stderr");if(Files.size(stderr)>0){warnings.add("Original runtime diagnostics were emitted; inspect worker/original.stderr and worker/original.stdout. They are retained verbatim and are not suppressed.");for(String line:Files.readAllLines(stderr,StandardCharsets.UTF_8))if(line.contains("WARN")||line.contains("Warning")||line.contains("Error"))warnings.add("ORIGINAL: "+line);}
            warnings.add("Complete native MatrixTable/Table outputs were reread with the original Hail implementation. Original missing/NaN/Inf values, sample order and source allele strings remain in the native files and typed snapshots. Liftover reports strand and keeps source alleles; it does not certify destination-reference alleles. LOCAL Batch checks do not certify job-program biology, Service/cloud scale or paper reproduction.");state.put("status","PASS_ORIGINAL_HAIL_WORKFLOWS");state.put("hail",runtime.expectedVersion());state.put("cases",report.get("cases"));state.put("cloud_batch_submitted",false);state.put("paper_reproduced",false);state.put("complete_native_readback_verified",true);state.put("finished_at",Instant.now().toString());warnings(out,state,warnings);var manifest=manifest(out,r,runtime);NextflowFiles.writeJson(out.resolve("manifest.json"),manifest);var manifestPin=NextflowFiles.pin(out.resolve("manifest.json"),67108864,()->{});state.put("manifest_sha256",manifestPin.sha256());state.put("result_admitted",true);status(out,state);exit=0;output.println("Hail complete batch admitted: "+out+"\nRead WARNINGS.md and analysis-status.json before using results.");
        }catch(HailWorkflowRuntime.Unavailable unavailable){exit=3;state.put("status","SKIP3_HAIL_DEPENDENCIES_UNAVAILABLE");state.put("error",unavailable.toString());warnings.add(unavailable.toString());error.println("HAIL SKIP3: "+unavailable+"\nREQUIRED ACTION: "+ACTION);}
        catch(Exception failure){state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("error",failure.toString());warnings.add(failure.toString());error.println("HAIL FAIL2: "+failure+"\nREQUIRED ACTION: "+ACTION);}
        finally{
            if(exit!=0&&out!=null){state.put("result_admitted",false);state.put("finished_at",Instant.now().toString());try{warnings(out,state,warnings);status(out,state);}catch(IOException failure){error.println("HAIL FAIL2: could not finalize prominent failure receipt: "+failure+". Keep the whole batch unadmitted.");exit=2;}}
        }
        return exit;
    }
    private static NextflowFiles.Pin capture(Path source,Path copy,HailWorkflowRequest.Request r,long[] bytes,int[] files)throws IOException {
        require(++files[0]<=r.maximumFiles(),"Complete input file capacity exceeded");var pin=NextflowFiles.pin(source,r.inputBytes()-bytes[0],()->{});Files.copy(source,copy);require(pin.equals(NextflowFiles.pin(copy,r.inputBytes()-bytes[0],()->{}))&&pin.equals(NextflowFiles.pin(source,r.inputBytes()-bytes[0],()->{})),"Input changed during original-byte capture");bytes[0]=Math.addExact(bytes[0],pin.bytes());return pin;
    }
    private static void validateCases(Path home,HailWorkflowRequest.Request r,Map<String,Object> report)throws IOException {
        var cases=list(report.get("cases"));for(int i=0;i<cases.size();i++){
            var result=object(cases.get(i));var requested=r.cases().get(i);String id=text(requested.get("id")),kind=text(requested.get("kind"));require(id.equals(text(result.get("id")))&&kind.equals(text(result.get("kind"))),"Original cases reordered or changed kind");Path path=home.resolve(id);
            if(kind.equals("matrix-pipeline")){
                var data=HailWorkflowRuntime.read(path.resolve("matrix-complete.json"),Math.toIntExact(Math.min(r.outputBytes(),268435456)));long rows=integer(data.get("row_count"),0,integer(r.limits().get("maximum_rows"),1,1000000000)),cols=integer(data.get("column_count"),0,integer(r.limits().get("maximum_columns"),1,1000000000));require(rows==list(data.get("rows")).size()&&cols==list(data.get("columns")).size()&&rows*cols<=integer(r.limits().get("maximum_entries"),1,1000000000),"Complete native matrix dimensions differ");for(Object row:list(data.get("rows")))require(list(object(row).get("__omicsmatic_entries")).size()==cols,"Complete native entry family differs");require(Files.isDirectory(path.resolve("result.mt"),LinkOption.NOFOLLOW_LINKS),"Final native MatrixTable missing");
            }else if(kind.equals("liftover")){var data=HailWorkflowRuntime.read(path.resolve("liftover.json"),Math.toIntExact(Math.min(r.outputBytes(),268435456)));require(list(data.get("rows")).size()==integer(result.get("rows"),0,1000000000)&&Files.isDirectory(path.resolve("liftover.ht"),LinkOption.NOFOLLOW_LINKS),"Complete native liftover table missing/incomplete");}
            else if(kind.equals("batch-local"))for(Object raw:list(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(path.resolve("complete-output-pins.json"),16777216)),16777216,1000000))){var file=object(raw);Path output=path.resolve("outputs").resolve(HailWorkflowRequest.id(file.get("job"))+"-"+HailWorkflowRequest.id(file.get("output")));require(NextflowFiles.fingerprint(file,r.outputBytes()).equals(NextflowFiles.pin(output,r.outputBytes(),()->{})),"Declared original Batch output missing/changed");}
        }
    }
    private static Map<String,Object> manifest(Path out,HailWorkflowRequest.Request r,HailWorkflowRuntime.Prepared runtime)throws IOException {
        var files=new TreeMap<String,Object>();var links=new TreeMap<String,Object>();var dirs=new TreeSet<String>();dirs.add("");long[] bytes={0};int[] count={0};
        Files.walkFileTree(out,new SimpleFileVisitor<>(){
            private void capacity(long size)throws IOException{require(++count[0]<=r.maximumFiles()&&size<=r.outputBytes()-bytes[0],"Complete output capacity exceeded; do not admit a partial batch");bytes[0]+=size;}
            @Override public FileVisitResult preVisitDirectory(Path path,BasicFileAttributes attrs)throws IOException{if(!path.equals(out)){capacity(0);dirs.add(out.relativize(path).toString().replace('\\','/'));}return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path path,BasicFileAttributes attrs)throws IOException{
                String name=out.relativize(path).toString().replace('\\','/');if(name.equals("analysis-status.json")||name.equals("manifest.json"))return FileVisitResult.CONTINUE;capacity(attrs.size());
                if(attrs.isSymbolicLink()){
                    Path target=Files.readSymbolicLink(path),logical=(target.isAbsolute()?target:path.getParent().resolve(target)).normalize();require(logical.startsWith(out)||logical.startsWith(runtime.prefix())||logical.startsWith(runtime.javaHome()),"Original output link targets an uncaptured location: "+path);var row=new LinkedHashMap<String,Object>();row.put("target",target.toString());row.put("resolved_logical_path",logical.toString());row.put("target_exists",Files.exists(path));if(Files.exists(path)){Path real=path.toRealPath();require(real.startsWith(out)||real.startsWith(runtime.prefix())||real.startsWith(runtime.javaHome()),"Output link resolution escapes captured roots");if(Files.isRegularFile(real))row.put("content",pinObject(NextflowFiles.pin(real,r.outputBytes(),()->{})));}links.put(name,row);
                }else{require(attrs.isRegularFile(),"Nonregular original output member");files.put(name,pinObject(NextflowFiles.pin(path,r.outputBytes(),()->{})));}return FileVisitResult.CONTINUE;
            }
        });return Map.of("schema_version",1,"directories",dirs,"files",files,"symlinks",links,"captured_regular_and_link_bytes",bytes[0],"admission_marker","analysis-status.json result_admitted=true; no directory relocation (original Batch scratch links remain auditable)");
    }
    private static Path canonicalMissing(Path path)throws IOException{var suffix=new ArrayDeque<Path>();Path current=path;while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"Missing canonical output ancestor");suffix.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path part:suffix)current=current.resolve(part);return current;}
    private static Map<String,Object> pinObject(NextflowFiles.Pin pin){return Map.of("bytes",pin.bytes(),"sha256",pin.sha256());}
    private static void status(Path out,Map<String,Object> state)throws IOException{Path temporary=out.resolve(".analysis-status-"+UUID.randomUUID()+".tmp");Files.writeString(temporary,NextflowJson.json(state)+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.move(temporary,out.resolve("analysis-status.json"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    private static void warnings(Path out,Map<String,Object> state,List<String> warnings)throws IOException{Files.writeString(out.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nRequired action: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
}
